def find_primal_pairs(target=800):
    pairs = []
    # Since p < r and p+r = 800, p must be less than 400.
    # We only need to check odd primes p (since 800 is even).
    for p in range(3, target // 2 + 1, 2):
        if is_prime(p):
            r = target - p
            if is_prime(r):
                pairs.append((p, r))
    return pairs

